#!/usr/bin/env python3
"""
======================== ÍNDICE / INDEX ========================
1. Propósito / Purpose
2. Lo más grave que borra / The worst thing it deletes
3. Las cuatro clases / The four classes
4. La red de seguridad / The safety net
5. ENGLISH

======================== ESPAÑOL ========================
Archivo: `.github/scripts/bootstrap_scrub.py`.

Un despliegue de VIGIL es un repositorio creado desde la plantilla, así que
nace con los archivos de datos del operador anterior dentro. Este script los
retira según lo que declara `.vigil/inherited.yaml`.

======================== LO MÁS GRAVE QUE BORRA ========================
`web/access.json`, y no es peso: es acceso.

El archivo está rastreado en la plantilla con **doce hashes SHA-256 de las
claves de acceso del operador anterior**. Un repositorio creado desde la
plantilla los hereda, así que las doce claves del autor abren el panel OPS del
nodo nuevo, y su operador no tendría forma de saberlo.

Y no se arreglaba solo: `wizard_seeds.py` se salta la generación cuando ya
existen doce seeds válidos —

    if existing.get("seeds") and len(existing["seeds"]) >= 12:
        print("Seeds already exist — skipping generation.")

— de modo que el arranque habría pasado por encima dejándolas en su sitio. El
borrado tiene que ocurrir **antes** de generar las nuevas. Por eso este script
corre primero, y por eso el arranque además pasa `FORCE_REGENERATE=true`: dos
cierres independientes sobre la misma puerta.

======================== LAS CUATRO CLASES ========================
Viven en `.vigil/inherited.yaml`, en YAML y no aquí dentro, porque quien
despliega tiene que poder leer qué se le borra sin leer Python.

  reset              se va; lo regenera quien sabe generarlo
  declare_reference  se queda, declarado como referencia y no como captura
  keep               el replay; el borrado falla si falta al terminar
  deferred           lo que no se toca todavía, con el motivo escrito

Lo que se borra no se sustituye por un esqueleto escrito a mano. Los esqueletos
escritos a mano se desincronizan del esquema real y entonces el panel lee un
documento que ya nadie genera. Se borra y lo regenera el exportador, que es
quien conoce el esquema.

======================== LA RED DE SEGURIDAD ========================
`keep` no es documentación: al terminar, el script comprueba que cada ruta
declarada sigue ahí y **falla** si falta alguna. Un borrado mal escrito que se
llevara por delante `tests/fixtures/hnd_2025/` dejaría al nodo nuevo sin lo
único que tiene que mostrar el día uno, y lo haría en silencio porque el panel
se vería igual de vacío que un nodo recién creado.

======================== ENGLISH ========================
File: `.github/scripts/bootstrap_scrub.py`.

A VIGIL deployment is a repository created from the template, so it is born
with the previous operator's data inside it. This removes it according to
`.vigil/inherited.yaml`.

The worst of it is `web/access.json`, and it is access rather than weight: the
template tracks twelve SHA-256 hashes of the previous operator's access keys,
so the author's twelve keys open the new node's OPS panel and its operator
would have no way of knowing. It did not fix itself either -- `wizard_seeds.py`
skips generation when twelve valid seeds already exist, so the bootstrap would
have walked past and left them in place. The deletion has to happen before the
new ones are generated, which is why this runs first and why the bootstrap also
passes FORCE_REGENERATE=true: two independent locks on the same door.

Nothing deleted is replaced by a hand-written skeleton. Hand-written skeletons
drift from the real schema and then the panel reads a document nobody
generates. It is deleted and regenerated by the exporter, which knows the
schema.

`keep` is not documentation: when it finishes, the script checks every declared
path is still there and fails if one is missing. A badly written scrub that
took `tests/fixtures/hnd_2025/` with it would leave the new node without the
one thing it has to show on day one, and would do it silently, because the
panel would look exactly as empty as a brand-new node's.
"""

from __future__ import annotations

import argparse
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

import yaml

MANIFEST = Path(".vigil/inherited.yaml")
REFERENCE_INDEX = Path("web/data/reference.json")


class ScrubError(RuntimeError):
    """El borrado no pudo completarse, y dejarlo a medias es peor."""


def load_manifest(path: Path) -> dict:
    if not path.exists():
        raise ScrubError(f"no hay manifiesto en {path}; sin el, este script no sabe que retirar")
    data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    if not isinstance(data, dict):
        raise ScrubError(f"{path} no es un mapa")
    if data.get("schema") != 1:
        raise ScrubError(f"{path} declara schema={data.get('schema')!r} y este script entiende 1")
    return data


def expand(root: Path, pattern: str) -> list[Path]:
    """Rutas existentes que casan, sean literales o con comodin."""
    if any(ch in pattern for ch in "*?["):
        return sorted(p for p in root.glob(pattern) if p.is_file())
    candidate = root / pattern
    return [candidate] if candidate.exists() else []


def action_delete(path: Path) -> str:
    path.unlink()
    return "borrado"


def action_empty_peers(path: Path) -> str:
    """Vacia la lista en vez de borrar el archivo.

    El panel lee `web/peers/<PAIS>.json` por ruta fija, asi que borrarlo da un
    404 donde una lista vacia dice la verdad: todavia no hay pares.

    English: the panel reads the file by fixed path, so deleting it yields a
    404 where an empty list tells the truth -- there are no peers yet.
    """
    path.write_text(json.dumps({"peers": []}, indent=2) + "\n", encoding="utf-8")
    return "vaciado"


ACTIONS = {"delete": action_delete, "empty_peers": action_empty_peers}


def apply_reset(root: Path, entries: list[dict], dry_run: bool) -> list[str]:
    report: list[str] = []
    for entry in entries:
        pattern = entry.get("path")
        name = entry.get("action")
        if not pattern or not name:
            raise ScrubError(f"entrada de `reset` incompleta: {entry!r}")
        handler = ACTIONS.get(name)
        if handler is None:
            raise ScrubError(f"accion desconocida {name!r} en `reset` para {pattern!r}; conocidas: {sorted(ACTIONS)}")

        targets = expand(root, pattern)
        if not targets:
            report.append(f"  - {pattern}: ausente, nada que hacer")
            continue
        for target in targets:
            relative = target.relative_to(root)
            if dry_run:
                report.append(f"  - {relative}: se habria {name}")
                continue
            report.append(f"  - {relative}: {handler(target)}")
    return report


def write_reference_index(root: Path, entries: list[dict], dry_run: bool) -> list[str]:
    """Declara los datos de referencia para que nadie los lea como propios.

    English: declares the reference data so that nobody reads it as this
    node's own captures.
    """
    declared = []
    for entry in entries:
        pattern = entry.get("path")
        if not pattern:
            raise ScrubError(f"entrada de `declare_reference` sin ruta: {entry!r}")
        declared.append(
            {
                "path": pattern,
                "present": bool(expand(root, pattern)),
                "why": " ".join(str(entry.get("why", "")).split()),
            }
        )

    document = {
        "schema": 1,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "label_es": "Conjunto de referencia (Honduras 2025). No es captura en vivo de este nodo.",
        "label_en": "Reference set (Honduras 2025). Not a live capture by this node.",
        "datasets": declared,
    }
    if dry_run:
        return [f"  - {REFERENCE_INDEX}: se habrian declarado {len(declared)} conjuntos"]

    target = root / REFERENCE_INDEX
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(document, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return [f"  - {REFERENCE_INDEX}: {len(declared)} conjuntos declarados"]


def verify_keep(root: Path, patterns: list[str]) -> list[str]:
    """La red: si falta algo de `keep`, el borrado se llevo lo que no debia."""
    missing = [pattern for pattern in patterns if not (root / pattern).exists()]
    if missing:
        raise ScrubError(
            "el borrado dejo sin estas rutas, que `keep` declara intocables: "
            f"{missing}. Es el replay, que es lo que el nodo nuevo muestra el dia uno."
        )
    return [f"  - {pattern}: intacto" for pattern in patterns]


def scrub(root: Path, manifest_path: Path, dry_run: bool = False) -> list[str]:
    manifest = load_manifest(manifest_path)
    lines: list[str] = []

    lines.append("reset — se va lo del operador anterior:")
    lines += apply_reset(root, manifest.get("reset") or [], dry_run)

    lines.append("declare_reference — se queda, declarado:")
    lines += write_reference_index(root, manifest.get("declare_reference") or [], dry_run)

    deferred = manifest.get("deferred") or []
    if deferred:
        total = sum(len(entry.get("paths") or []) for entry in deferred)
        lines.append(f"deferred — {total} archivo(s) que no se tocan todavia, con el motivo en el manifiesto")

    lines.append("keep — la red:")
    lines += verify_keep(root, list(manifest.get("keep") or []))
    return lines


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Retira los datos heredados de la plantilla.")
    parser.add_argument("--root", default=".", help="Raiz del repositorio del nodo.")
    parser.add_argument("--manifest", default="", help=f"Manifiesto; por defecto <root>/{MANIFEST}.")
    parser.add_argument("--dry-run", action="store_true", help="Dice lo que haria y no toca nada.")
    args = parser.parse_args(argv)

    root = Path(args.root)
    manifest_path = Path(args.manifest) if args.manifest else root / MANIFEST

    try:
        lines = scrub(root, manifest_path, args.dry_run)
    except ScrubError as exc:
        print(f"bootstrap_scrub=FAIL {exc}", file=sys.stderr)
        return 1

    prefix = "DRY-RUN " if args.dry_run else ""
    print(f"{prefix}bootstrap_scrub=PASS")
    for line in lines:
        print(line)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
